import{_ as a,o as t,c as r,ag as i}from"./chunks/framework.D9kpkP22.js";const h=JSON.parse('{"title":"Features","description":"","frontmatter":{},"headers":[],"relativePath":"icedspear/features.md","filePath":"icedspear/features.md"}'),s={name:"icedspear/features.md"};function n(l,e,o,d,c,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h1><p>IcedSpear is packed with features designed to make lobby and map management effortless.</p><h2 id="map-management" tabindex="-1">Map Management <a class="header-anchor" href="#map-management" aria-label="Permalink to &quot;Map Management&quot;">​</a></h2><p>The core of IcedSpear is its dynamic map instance system. Unlike standard multi-world plugins, IcedSpear treats maps as temporary or persistent instances that can be created on demand.</p><h3 id="instance-types" tabindex="-1">Instance Types <a class="header-anchor" href="#instance-types" aria-label="Permalink to &quot;Instance Types&quot;">​</a></h3><ul><li><strong>Public Maps</strong>: Shared instances accessible by anyone via the map selector or commands. Great for main lobbies or open game modes. <ul><li>ID Format: <code>PUBLIC_&lt;mapName&gt;</code></li></ul></li><li><strong>Private Maps</strong>: Exclusive instances created for specific players or groups. <ul><li>ID Format: <code>&lt;mapName&gt;_&lt;randomCode&gt;</code></li></ul></li><li><strong>Party Maps</strong>: Private instances specifically reserved for a party. <ul><li>ID Format: <code>&lt;mapName&gt;_party-&lt;partyCode&gt;</code></li></ul></li></ul><h3 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h3><ol><li><strong>Creation</strong>: When a map is requested, IcedSpear asynchronously generates a new world using a lightweight void generator.</li><li><strong>Initialization</strong>: Schematics are pasted (if configured) and game rules are applied.</li><li><strong>Active</strong>: Players play in the instance.</li><li><strong>Cleanup</strong>: When the last player leaves (plus a configurable delay), the world is unloaded and deleted to save resources.</li></ol><h2 id="party-system" tabindex="-1">Party System <a class="header-anchor" href="#party-system" aria-label="Permalink to &quot;Party System&quot;">​</a></h2><p>IcedSpear includes a fully-featured party system to keep friends together.</p><h3 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h3><ul><li><strong>Creation</strong>: Any player can create a party and become the leader.</li><li><strong>Invites</strong>: Leaders can invite other players via <code>/party invite &lt;player&gt;</code>.</li><li><strong>Warping</strong>: When the party leader joins a map, all party members are automatically warped to that same map instance.</li><li><strong>Chat</strong>: A dedicated party chat channel (if enabled).</li></ul><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li><code>/party create</code>: Start a new party.</li><li><code>/party invite &lt;player&gt;</code>: Send an invitation.</li><li><code>/party join &lt;code&gt;</code> or <code>/party accept &lt;player&gt;</code>: Join a party.</li><li><code>/party leave</code>: Leave your current party.</li></ul><h2 id="friend-system" tabindex="-1">Friend System <a class="header-anchor" href="#friend-system" aria-label="Permalink to &quot;Friend System&quot;">​</a></h2><p>Build a community with the integrated friend system.</p><ul><li><strong>Friend Requests</strong>: Send and receive friend requests.</li><li><strong>Online Status</strong>: See which friends are online and what map they are playing on.</li><li><strong>Quick Actions</strong>: Easily invite friends to your party.</li></ul><h2 id="leaderboards" tabindex="-1">Leaderboards <a class="header-anchor" href="#leaderboards" aria-label="Permalink to &quot;Leaderboards&quot;">​</a></h2><p>Foster competition with built-in leaderboards.</p><ul><li><strong>Per-Map Tracking</strong>: Track fastest times, high scores, or other metrics for each specific map.</li><li><strong>Global &amp; Instance</strong>: View global top players or just the leaders in your current instance.</li><li><strong>Holograms</strong>: (Optional) Display leaderboards in-game using hologram integrations.</li></ul>',20)])])}const u=a(s,[["render",n]]);export{h as __pageData,u as default};
